def audit(nb):
    problems = []
    highest=-1
    for i,c in enumerate(nb["cells"]):
        if c["cell_type"]!="code":
            continue
        n=c["execution_count"]
        if n is not None:
            if n<highest: problems.append((i,"order"))
            highest=max(n,highest)
        source="".join(c["source"])
        if any(source[j+1:j+2]=="/" or (source[j+1:j+2].isalpha() and source[j+2:j+3]==":") for j,ch in enumerate(source) if ch in ("'",chr(34))):
            problems.append((i,"abs_path"))
        if any(o["output_type"]=="error" for o in c["outputs"]): problems.append((i,"error"))
        lines=[l.strip() for l in source.splitlines() if l.strip()]
        if lines and all(l.startswith("#") for l in lines): problems.append((i,"commented"))
    return problems

