import pandas as pd

def summary(full):
    m=full.groupby(full.datetime.dt.to_period("M")).amount.sum()
    growth=round((m.iloc[-1]/m.iloc[-2]-1)*100,1) if len(m)>=2 else float("nan")
    return dict(revenue=full.amount.sum(),orders=len(full),avg_check=round(full.amount.mean(),1),best_city=full.groupby("city").amount.sum().idxmax(),top_drink=full.drink.value_counts().idxmax(),growth_pct=growth)

