def status(committed, working, ignore):
    new=sorted(p for p in working.keys()-committed.keys() if not any(fnmatch(p.split("/")[-1],pat) for pat in ignore))
    modified=sorted(p for p in working.keys()&committed.keys() if working[p]!=committed[p])
    deleted=sorted(committed.keys()-working.keys())
    return dict(new=new,modified=modified,deleted=deleted)

status(committed, working, ignore)

import copy
import difflib
import json

def changed_lines(a, b):
    lines=difflib.unified_diff(a.splitlines(),b.splitlines())
    return sum(l.startswith(("+","-")) and not l.startswith(("+++","---")) for l in lines)

def strip(nb):
    out=copy.deepcopy(nb)
    for c in out["cells"]:
        if c["cell_type"]=="code":
            c["outputs"]=[]
            c["execution_count"]=None
    return out

