def review(repos):
    out={}
    for repo,files in repos.items():
        errors=[]
        if "README.md" not in files: errors.append("no_readme")
        if ".gitignore" not in files: errors.append("no_gitignore")
        if not any(p.endswith(".ipynb") for p in files): errors.append("no_notebook")
        if any(p.split("/")[-1]==".env" for p in files): errors.append("secrets")
        if any(p.startswith("data/") for p in files): errors.append("data")
        if errors: out[repo]=errors
    return out

